def find_path(graph, start, goal):
    visited = set()
    stack = [[start]]

    if start == goal:
        return [start]

    while stack:
        path = stack.pop()
        node = path[-1]

        if node not in visited:
            for neighbour in graph.get(node, []):
                new_path = list(path)
                new_path.append(neighbour)
                if neighbour == goal:
                    return new_path
                else:
                    stack.append(new_path)
            visited.add(node)

    return None
